<script setup lang="ts">
import {computed} from 'vue';import VChart from 'vue-echarts';import {use} from 'echarts/core';import {CanvasRenderer} from 'echarts/renderers';import {LineChart} from 'echarts/charts';import {GridComponent,TooltipComponent,DataZoomComponent,MarkAreaComponent} from 'echarts/components';import type {Point,Lap} from '../types';import {formatDuration} from '../utils';
use([CanvasRenderer,LineChart,GridComponent,TooltipComponent,DataZoomComponent,MarkAreaComponent]);
const p=withDefaults(defineProps<{points:Point[],laps?:Lap[],detail?:boolean,duration:number}>(),{laps:()=>[],detail:false});
const option=computed(()=>({animation:false,grid:{left:45,right:45,top:18,bottom:p.detail?62:28},tooltip:{trigger:'axis'},xAxis:{type:'value',min:0,max:p.duration,axisLabel:{formatter:formatDuration}},yAxis:[{type:'value',name:'W',scale:true},{type:'value',name:'bpm',scale:true}],dataZoom:p.detail?[{type:'inside'},{type:'slider',bottom:10}]:[],series:[{name:'Potenza',type:'line',showSymbol:false,sampling:'lttb',lineStyle:{width:1,color:'#2563eb'},data:p.points.map(x=>[x.elapsedSeconds,x.power]),markArea:p.laps.length?{silent:true,itemStyle:{color:'rgba(37,99,235,.06)'},data:p.laps.map(l=>[{xAxis:l.startElapsedSeconds},{xAxis:l.endElapsedSeconds}])}:undefined},{name:'HR',type:'line',yAxisIndex:1,showSymbol:false,sampling:'lttb',lineStyle:{width:1.5,color:'#dc2626'},data:p.points.map(x=>[x.elapsedSeconds,x.heartRate])}]}))
</script><template><VChart class="chart" :option="option" autoresize /></template>
